"""Build a local, anonymous Korean HTML pitch from actual captured app screens."""
import base64
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'artifacts/pitch/current'


def image(path, label):
    data = base64.b64encode((ROOT / path).read_bytes()).decode('ascii')
    return '<img alt="' + escape(label) + '" src="data:image/png;base64,' + data + '">'


def main():
    shots = ROOT / 'docs/screenshots/intent-review'
    assert all((shots / (name + '.png')).is_file() for name in ['pending', 'confirmed', 'explanation', 'night', 'driving-lock'])
    def shot(name, label):
        return image('docs/screenshots/intent-review/' + name + '.png', label)
    slides = [
        ('퇴근길의 질문', '<div class="split"><div><p class="eyebrow">OnMyWay AI</p><h1>꼭 할 일은 끝내고,<br>집에는 제시간에.</h1><p class="lead">귀가 마감이 있는 운전자의<br>퇴근길 완료 플래너</p><p class="muted">약은 꼭, 세탁물은 6시 반 전.<br>우유까지 사도 7시에 집에 갈 수 있을까요?</p></div><figure>' + shot('pending', '준비된 예시 요청의 질문과 빠진 귀가 시간') + '<figcaption>실제 앱 · 준비된 예시 해석 / 실제 STT·LLM 결과 아님</figcaption></figure></div>'),
        ('확인 가능한 요청', '<h1>애매한 말은 묻고,<br>없는 조건은 직접 확인합니다.</h1><div class="split"><figure>' + shot('confirmed', '답변과 귀가 시간을 반영한 실제 검토 화면') + '</figure><div class="stack"><article><b>01 · 수령 완료 마감</b><p>“6시 반 전”이 도착인지 완료인지 질문</p></article><article><b>02 · 귀가 시간</b><p>말하지 않은 19:00을 임의로 채우지 않음</p></article><article><b>03 · 사용자 검토</b><p>원문·필수 2개·선택 1개를 비교하고 수정</p></article></div></div>'),
        ('최종 귀가까지', '<p class="eyebrow">정상 예시 · 가상 장소·시간 / 모의 안내·도착</p><h1>도착은 완료가 아닙니다.</h1><div class="flow"><article><b>18:15</b><p>약 구매 완료</p></article><i>→</i><article><b>18:25</b><p>세탁물 완료</p></article><i>→</i><article><b>18:35</b><p>우유 구매 완료</p></article><i>→</i><article><b>18:40</b><p>최종 귀가</p></article></div><div class="cards"><article><h2>매번 새 승인</h2><p>현재의 최신 계획에서 다음 목적지만 직접 승인합니다.</p></article><article><h2>직접 완료 확인</h2><p>도착 후 할 일을 마쳤다고 확인해야 남은 일만 재계산합니다.</p></article><article><h2>집도 별도 승인</h2><p>최종 귀가 구간을 계산하고 집 안내도 따로 승인합니다.</p></article></div><p class="muted">18:00 출발 → 19:00 마감에 20분 여유. 실제 교통·효과 측정값이 아닙니다.</p>'),
        ('불가능한 조건', '<div class="split"><div><p class="eyebrow">촉박한 예시 · 계산 결과</p><h1>필수 일을<br>몰래 빼지 않습니다.</h1><p class="metric">18:20 <span>→</span> 18:31</p><p class="lead">11분 연장을 제안하고<br>승인받은 뒤 다시 계산</p><p class="muted">필수 2개 유지 · 선택 우유 제외를 표시<br>정보 부족은 실행 가능과 구분</p></div><figure>' + shot('explanation', '실제 계산 근거와 선택 우유 제외') + '<figcaption>예시 해석·가상 이동시간 · 확인된 계산 결과에서 설명</figcaption></figure></div>'),
        ('차량 안의 경험', '<h1>정차 중 판단하고,<br>주행 제한을 따릅니다.</h1><div class="split"><figure>' + shot('driving-lock', '실제 Drive 30km/h 조작 제한') + '<figcaption>실제 CarUxRestrictions · Drive 30 km/h</figcaption></figure><figure>' + shot('night', '시스템 야간 모드의 실제 앱') + '<figcaption>한 번에 한 행동 · 시스템 주야간 · 상세는 펼쳐 보기</figcaption></figure></div><p class="muted">공식 Pleos 에뮬레이터 검증. 물리 차량 사용성·안전 인증은 수행하지 않았습니다.</p>'),
        ('AI와 검증 범위', '<p class="eyebrow">기술 활용성 · 구현과 검증을 구분</p><h1>AI는 조건을 정리하고,<br>계산 엔진은 시간을 검토합니다.</h1><div class="cards"><article><h2>AI 연결 경로</h2><p>요청·확인 답변 → 구조화<br>원문 비교·사용자 수정<br>필수·기존 시간 조건 보존</p><small>이번 시연은 준비된 해석</small></article><article><h2>검증한 계산·상태</h2><p>이동 + 대기 + 체류 + 귀가<br>불가능·정보 부족 구분<br>새 계획 승인·명시적 완료</p><small>Python 30개 · Android 변형당 41개</small></article><article><h2>남은 실연동 검증</h2><p>최종 한국어 STT<br>LLM·Kakao 실호출<br>내비 경로 수락·실제 도착</p><small>STT 듣기·취소와 내비 연결은 확인</small></article></div><p class="muted">키는 나중에 서버에만 설정. 실패한 실제 호출을 예시로 대체하지 않습니다.</p>'),
        ('사업 가설과 출시', '<p class="eyebrow">사업성 · 실적·인터뷰 없음 / 계산과 검증 계획</p><h1>작게 검증하고,<br>반복되는 효용을 확인합니다.</h1><div class="split"><div><p class="lead">초기 고객: 귀가 마감이 있는<br>자동차 출퇴근 운전자</p><div class="metric">60 <span>→</span> 84 <span>→</span> 94</div><p>1·2·3개월차 MAU 계산 예시</p><p class="muted">월 도달 200 × 설치 50% × 활성 60%<br>월 재사용 40% 가정. D7 리텐션과 다른 지표.</p></div><div class="stack"><article><b>수요 확인</b><p>승인 후 과제 관찰 → 2주 파일럿<br>완료·D7 재사용·오류·지불 의사</p></article><article><b>출시 조건</b><p>실데이터·영업·수령 가능 검증 → 실제 차량<br>인증·삭제·공유 차량 정책·호출 비용</p></article><article><b>확장 후보</b><p>저장 루틴·충전 대기 용무<br>제휴·매출·입점 확보를 주장하지 않음</p></article></div></div>')
    ]
    sections = ''.join('<section' + (' class="active"' if i == 0 else '') + ' aria-label="' + escape(label) + '">' + body + '<div class="page">' + str(i+1) + ' / ' + str(len(slides)) + '</div></section>' for i, (label, body) in enumerate(slides))
    css = '''*{box-sizing:border-box} :root{--bg:#101820;--panel:#1c2730;--text:#f4f6f5;--muted:#b8c5cc;--accent:#b9dcd8}body{margin:0;background:var(--bg);color:var(--text);font-family:"Malgun Gothic",sans-serif}section{display:none;position:relative;min-height:calc(100vh - 65px);padding:5vh 5vw 6vh}section.active{display:flex;flex-direction:column;justify-content:center;gap:2vh}h1{font-size:clamp(32px,3.5vw,60px);line-height:1.3;letter-spacing:-.05em;margin:0 0 2vh}h2{font-size:clamp(22px,2vw,32px);margin:0 0 20px}p{line-height:1.65;font-size:clamp(17px,1.45vw,25px);margin:12px 0}.eyebrow{color:var(--accent);font-size:18px;letter-spacing:.04em}.lead{font-size:clamp(22px,2.2vw,36px)}.muted,figcaption,small{color:var(--muted)}.split{display:grid;grid-template-columns:1fr 1.1fr;align-items:center;gap:3vw}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}article{background:var(--panel);padding:24px;border-radius:18px;border:1px solid #354550}article b{font-size:24px;color:var(--accent)}.stack{display:grid;gap:16px}.stack article{padding:16px 24px}.stack p{margin:8px 0}figure{margin:0}img{width:100%;height:auto;display:block;border-radius:12px;border:1px solid #44515a}figcaption{font-size:17px;line-height:1.5;margin-top:14px}.flow{display:flex;align-items:center;gap:16px;margin:20px 0}.flow article{flex:1}.flow b{font-size:40px}.flow i{font-size:30px;color:var(--muted)}.metric{font-size:clamp(32px,3.5vw,60px);font-weight:700;color:var(--accent);white-space:nowrap}.metric span{font-size:30px;color:var(--muted)}small{font-size:16px;line-height:1.5}.page{position:absolute;right:5vw;bottom:20px;color:var(--muted);font-size:18px}nav{height:65px;display:flex;align-items:center;justify-content:space-between;padding:8px 5vw;border-top:1px solid #354550;color:var(--muted);font-size:15px}button{border:1px solid #637784;background:#263943;color:var(--text);padding:10px 22px;border-radius:12px;font:inherit;font-size:18px;cursor:pointer}button:focus-visible{outline:3px solid var(--accent)}@media(max-width:900px){.split,.cards{grid-template-columns:1fr}.flow{flex-wrap:wrap}.flow article{min-width:130px}section{padding:30px 6vw 65px}nav{height:auto;min-height:65px;gap:12px;flex-wrap:wrap}.page{bottom:18px}img{max-height:40vh;object-fit:contain}}@media print{section,section.active{display:flex;page-break-after:always;height:100vh}nav{display:none}}'''
    css += '@media(min-width:901px){section{padding:3vh 5vw;gap:1.5vh}h1{font-size:clamp(32px,3vw,54px);line-height:1.25;margin-bottom:1vh}p{font-size:clamp(17px,1.3vw,23px)}.lead{font-size:clamp(22px,2vw,34px)}.stack article{padding:12px 20px}.stack article b{font-size:22px}.metric{font-size:clamp(32px,3vw,54px)}.flow article{padding:20px}}'
    html = '<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OnMyWay AI · 퇴근길 완료 플래너</title><style>' + css + '</style><main>' + sections + '</main><nav><span>익명 발표 자료 · 2026-10-24 · 실제 화면 / 예시·미검증 범위 표기</span><div><button id="prev" aria-label="이전 슬라이드">이전</button> <button id="next" aria-label="다음 슬라이드">다음</button></div></nav><script>const slides=[...document.querySelectorAll("section")];let index=0;function show(n){index=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle("active",i===index));document.getElementById("prev").disabled=index===0;document.getElementById("next").disabled=index===slides.length-1;}document.getElementById("prev").onclick=()=>show(index-1);document.getElementById("next").onclick=()=>show(index+1);document.addEventListener("keydown",e=>{if(e.key==="ArrowRight")show(index+1);if(e.key==="ArrowLeft")show(index-1);});show(0);</script></html>'
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / 'index.html').write_text(html, encoding='utf-8')
    print('Built 7 Korean slides with 5 embedded actual screenshots; local output: artifacts/pitch/current/index.html')


if __name__ == '__main__':
    main()
